files.sketch.js:
/* WALLET WATCH - an agentic p0pc0rn app that watches public Avalanche C-Chain addresses (wallets or contracts) and tells you what
   changed. Paste an address in the open app (or keep the public WAVAX example): while p0pc0rn is open it looks at each one at most every
   15 minutes (30 to start), only when the phone is idle, through Snowtrace, the public Avalanche explorer (the host fetches it: only the
   addresses go out), notes what is new, brings it to its "What changed" list and posts one short notice in Juli's chat. Juli writes that
   notice and, once a day, a few sentences on a wallet's habits (when it is active, what it deals with, typical sizes); her words are
   kept only when every number in them is in Snowtrace's data (K.facts) and they give no advice and no guess about who is behind an
   address. Otherwise the app's own words are used.
   It only reads public data: it never touches a wallet, never moves anything and never gives advice of any kind.
   The five parts of an agentic app (Skeleton Guide, "Two kinds of app"):
     goal      manifest.goal: keep an eye on the addresses I watch and tell me what changed
     notebook  K.notebook('watch'): confirmed = the addresses you added; grounding = where each one stands (its last block, balance,
               newest activity, its contract code) and the explorer's public labels; suspected = what changed (the review list) and
               each wallet's habits; dismissed = what you said "Got it" to
     tasks     active (the open app): add or remove an address, "Got it". idle: 'watch' (every 15-60 minutes, under Snowtrace's free
               limit: makeapp/budget.js caps every app together and each app), 'habits' (a wallet's, at most once a day), 'tidy'
     reach     chain.snowtrace (read only), and Juli (permissions.juli ["ask"]) with her watch-a-wallet skill
     review    K.review(): what changed, with its source and time. Nothing happens on its own: it only tells you.
   Everything it keeps stays on this phone. */
// ===== CORE (pure: no p5, no p0, no K: node-tested as it ships, v39/tests/walletwatch/core.test.mjs) =====
// What changed at a public Avalanche address, what is worth a notice, the notice's own words, the check that keeps Juli's words grounded,
// and a wallet's habits in numbers. Amounts arrive as integer strings (wei, token units) and are never guessed at.
const WW = (() => {
  const ADDR = /^0x[0-9a-fA-F]{40}$/;
  const low = (a) => String(a == null ? '' : a).trim().toLowerCase();
  const isAddr = (a) => ADDR.test(String(a == null ? '' : a).trim());
  const short = (a) => { const s = low(a); return ADDR.test(s) ? s.slice(0, 6) + '…' + s.slice(-4) : s.slice(0, 14); };
  const clip = (s, n) => String(s == null ? '' : s).replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
  const and = (l) => { l = l.filter(Boolean); return l.length <= 1 ? l.join('') : l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1]; };
  const plural = (n, w, ws) => `${n} ${n === 1 ? w : ws || w + 's'}`;
  const WD = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const DEF = {
    time: (ms) => new Date(ms).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }),
    hourOf: (t) => new Date(t * 1000).getHours(), dayOf: (t) => new Date(t * 1000).getDay(),
    dateOf: (t) => { const d = new Date(t * 1000); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); },
    hourLabel: (h) => new Date(2000, 0, 1, h).toLocaleTimeString([], { hour: 'numeric' }),
    wdLabel: (d) => WD[d], dateLabel: (ymd) => { const m = /^(\d{4})-(\d\d)-(\d\d)$/.exec(ymd); return m ? MON[+m[2] - 1] + ' ' + +m[3] : ymd; },
    nameOf: short,
  };
  const opt = (o) => Object.assign({}, DEF, o || {});

  // ---- amounts
  /** an integer string with its decimals -> a number (for sizes and order; the strings stay the truth) */
  function units(raw, dec) {
    const s = /^\d+$/.test(String(raw)) ? String(raw).replace(/^0+(?=\d)/, '') : '0', d = Math.max(0, Math.min(36, dec | 0));
    if (!d) return Number(s);
    return Number((s.length > d ? s.slice(0, s.length - d) : '0') + '.' + (s.length > d ? s.slice(s.length - d) : s.padStart(d, '0')));
  }
  /** a number as people write it: 18,082,172 · 120.5 · 1.16 · 0.00422 (the same string goes into the facts Juli's words are checked against) */
  function fmt(n) {
    if (!Number.isFinite(n) || n <= 0) return '0';
    if (n >= 1000) return Math.round(n).toLocaleString('en-US');
    if (n >= 1) return String(Math.round(n * 100) / 100);
    if (n >= 0.0001) return String(Number(n.toPrecision(3)));
    return 'less than 0.0001';
  }
  const weiDelta = (a, b) => { try { const d = BigInt(b) - BigInt(a); return (d < 0n ? -1 : 1) * units((d < 0n ? -d : d).toString(), 18); } catch (e) { return 0; } };

  // ---- what to watch, and how often
  /** the design's addresses (slots) minus the ones the person removed, then the ones they added in the app: at most `max`, never twice */
  function watchList(slotList, yours, removed, max = 5) {
    const out = [], seen = new Set((removed || []).map(low));
    const add = (x, from) => {
      if (!x || out.length >= max) return;
      const a = low(x.address); if (!isAddr(a) || seen.has(a)) return; seen.add(a);
      out.push({ address: a, label: clip(x.label, 20) || short(a), kind: x.kind === 'contract' ? 'contract' : 'wallet', from });
    };
    for (const x of Array.isArray(slotList) ? slotList : []) add(x, 'slot');
    for (const x of Array.isArray(yours) ? yours : []) add(x, 'you');
    return out;
  }
  // Snowtrace's free limit is 10,000 requests a day; p0pc0rn stops every app together at 5,000 and any one app at 1,600 (makeapp/budget.js,
  // the host's hard cap). The worst case of one Wallet Watch (every address changed at every check, p0pc0rn open all day) at its floor of
  // 15 minutes: 96 checks x (1 + 3 x 5 wallets) + 30 = 1,566 <= 1,600; at its 30 to start, the public WAVAX contract alone: 48 x 3 + 2 =
  // 146 a day. A slower look is chosen only when a ceiling needs it.
  const DAY_BUDGET = 1600, FLOOR = 15, START = 30;
  const perCheck = (w, c) => 1 + 3 * w + 2 * c;     // the balances (one request), then a wallet's calls, tokens, internal; a contract's calls, tokens
  const perDayExtra = (w, c) => 6 * w + 2 * c;      // once a day: a wallet's history (3) and its counterparties' labels (up to 3); a contract's source and label
  const dayWorst = (m, w, c) => Math.ceil(1440 / m) * perCheck(w, c) + perDayExtra(w, c);
  /** the minutes between checks: the person's slot (15-60, rounded up to 5; 30 when it has none), longer only when the ceiling needs it */
  function everyFor(slot, w, c) {
    let m = Math.max(FLOOR, Math.min(60, Math.ceil((Number.isFinite(+slot) && +slot > 0 ? +slot : START) / 5) * 5));
    while (m < 60 && dayWorst(m, w, c) > DAY_BUDGET) m += 5;
    return m;
  }

  // ---- events: an address's rows (makeapp/snowtrace.js) as what happened, newest first
  //   out / in: AVAX sent or received (a contract's internal transfers count too); tout / tin: a token; call: a contract call without AVAX;
  //   fail: a transaction of its own that failed; hit: someone used the contract (a contract)
  // a row's key, short (a notebook entry holds at most 40 KB): the last 16 hex of its transaction hash, and a digest of the rest for the parts of one
  const fnv = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619) >>> 0; return h.toString(36); };
  const keyTx = (r) => 'x' + String(r.h).slice(-16), keyInt = (r) => 'i' + String(r.h).slice(-16) + fnv(r.f + r.to + r.v), keyTok = (r) => 't' + String(r.h).slice(-16) + fnv(r.c + r.f + r.to + r.v);
  function eventsOf(address, kind, rows) {
    const me = low(address), ev = [], R = rows || {};
    for (const r of R.txs || []) {
      const base = { key: keyTx(r), h: r.h, b: r.b, t: r.t };
      if (kind === 'contract' && r.to === me && r.f !== me) { ev.push(Object.assign(base, { k: 'hit', cp: r.f, fn: r.fn, avax: r.err ? 0 : units(r.v, 18) })); continue; }
      if (r.err) { if (r.f === me) ev.push(Object.assign(base, { k: 'fail', cp: r.to, fn: r.fn })); continue; }
      if (r.f === me && r.to === me) continue;
      const v = units(r.v, 18);
      if (r.f === me) ev.push(Object.assign(base, v > 0 ? { k: 'out', cp: r.to, avax: v } : { k: 'call', cp: r.to, fn: r.fn }));
      else if (r.to === me && v > 0) ev.push(Object.assign(base, { k: 'in', cp: r.f, avax: v }));
    }
    for (const r of R.int || []) {
      if (r.err) continue;
      const v = units(r.v, 18); if (!(v > 0)) continue;
      if (r.to === me && r.f !== me) ev.push({ key: keyInt(r), h: r.h, b: r.b, t: r.t, k: 'in', cp: r.f, avax: v });
      else if (r.f === me && r.to !== me) ev.push({ key: keyInt(r), h: r.h, b: r.b, t: r.t, k: 'out', cp: r.to, avax: v });
    }
    for (const r of R.tok || []) {
      const n = units(r.v, r.dec); if (!(n > 0)) continue;   // a 0-value token transfer is a common spam: never an event
      if (r.to === me && r.f !== me) ev.push({ key: keyTok(r), h: r.h, b: r.b, t: r.t, k: 'tin', cp: r.f, amt: n, sym: r.sym, c: r.c });
      else if (r.f === me && r.to !== me) ev.push({ key: keyTok(r), h: r.h, b: r.b, t: r.t, k: 'tout', cp: r.to, amt: n, sym: r.sym, c: r.c });
    }
    return ev.sort((x, y) => y.b - x.b || y.t - x.t);
  }

  /** one check of one address. prev = its state (null: the first look, which only notes where things stand), item = the watch op's row
   *  for it, bal = its balance (wei) -> {state, first, events (new), recent (its newest, for its card), hits, moves, busy, more, balance, prevAt} */
  function step(prev, item, bal, o) {
    o = o || {}; const now = o.now || Date.now(), me = low(item.address), kind = item.kind === 'contract' ? 'contract' : 'wallet';
    const rows = { txs: item.txs || [], tok: item.tok || [], int: item.int || [] }, all = eventsOf(me, kind, rows);
    const first = !prev || !prev.head;
    const st = Object.assign({ head: 0, seen: [], bal: null, since: now, checks: 0, hits: 0, moves: 0, rate: null, lastAt: 0, lastAct: 0 }, prev || {});
    const seen = new Set(st.seen), oldHead = st.head;
    const fresh = first ? [] : all.filter((e) => !seen.has(e.key) && e.b >= oldHead);
    const blocks = [].concat(rows.txs, rows.tok, rows.int).map((r) => r.b || 0);
    st.head = Math.max(oldHead, ...blocks, 0);
    // the next check asks from st.head on (inclusive): what is at that block now is seen
    const keys = [].concat(rows.txs.filter((r) => r.b >= st.head).map(keyTx), rows.int.filter((r) => r.b >= st.head).map(keyInt), rows.tok.filter((r) => r.b >= st.head).map(keyTok));
    st.seen = [...new Set(st.head === oldHead ? st.seen.concat(keys) : keys)].slice(-300);
    const before = st.bal, after = bal != null ? String(bal) : before;
    const prevAt = st.lastAt;
    st.bal = after; st.checks += 1; st.lastAt = now;
    const acts = (first ? all : fresh).map((e) => e.t * 1000);
    if (acts.length) st.lastAct = Math.max(st.lastAct || 0, ...acts);
    const hits = fresh.filter((e) => e.k === 'hit').length, moves = fresh.filter((e) => /^(in|out|tin|tout)$/.test(e.k)).length;
    st.hits += hits; st.moves += moves;
    let busy = null;
    if (kind === 'contract' && !first) {   // its pace: interactions a minute, averaged over its checks; a busy spell = 3 times that, and 30 or more
      const mins = Math.max(1, (now - (prevAt || now)) / 60e3), pace = hits / mins, r = st.rate || { avg: 0, n: 0 };
      if (r.n >= 3 && r.avg > 0 && hits >= 30 && pace >= 3 * r.avg) busy = { hits, times: Math.floor(pace / r.avg) };
      st.rate = { avg: r.n ? r.avg * 0.8 + pace * 0.2 : pace, n: r.n + 1 };
    }
    const full = item.full || {}, more = !first && !!(full.txs || full.tok || full.int);
    const delta = before != null && after != null && before !== after ? weiDelta(before, after) : 0;
    return { state: st, first, events: fresh, recent: all.slice(0, 8), hits, moves, busy, more, balance: { before, after, delta }, prevAt };
  }

  // ---- a contract's code: what it was the last time, and what changed
  const codeKnown = (prev, info) => ({ known: true, verified: !!info.verified, name: clip(info.name, 40), proxy: !!info.proxy, impl: low(info.impl), at: Date.now() });
  function codeChange(prev, info) {
    if (!prev || !prev.known || !info) return null;
    const out = {};
    if (!prev.verified && info.verified) out.verified = { name: clip(info.name, 40) };
    if (prev.verified && !info.verified) out.unverified = true;
    if (prev.proxy !== !!info.proxy) out.proxy = { now: !!info.proxy };
    const to = low(info.impl);
    if (to && to !== prev.impl) out.impl = { from: prev.impl || '', to };
    return Object.keys(out).length ? out : null;
  }

  /** the events worth a notice, by the person's choice: 'changes' (AVAX and tokens in and out; a contract: its code and busy spells, told
   *  apart), 'big' (AVAX moves of at least `big`), 'all' (everything, a contract's every interaction), 'quiet' (none); never on a first look */
  function worth(res, kind, mode, big) {
    if (!res || res.first || mode === 'quiet') return [];
    const ev = res.events || [];
    if (kind === 'contract') {
      if (mode === 'all') return ev.slice();
      if (mode === 'big') return ev.filter((e) => (e.avax || 0) >= big);
      return [];
    }
    if (mode === 'all') return ev.slice();
    if (mode === 'big') return ev.filter((e) => (e.k === 'in' || e.k === 'out') && e.avax >= big);
    return ev.filter((e) => /^(in|out|tin|tout)$/.test(e.k));
  }

  // ---- the notice: its facts (every word and number Juli may use) and the app's own words
  const VERB = { out: 'sent', in: 'received', tout: 'sent', tin: 'received', call: 'used', fail: 'tried to use', hit: 'was used by' };
  const PREP = { out: 'to', in: 'from', tout: 'to', tin: 'from', call: '', fail: '', hit: '' };
  /** w = {label, kind}; res = step()'s result; list = worth(); code = codeChange(); o = {nameOf, time, all} -> the facts */
  function noticeFacts(w, res, list, code, o) {
    o = opt(o); const items = [];
    const pick = list.filter((e) => e.avax > 0).sort((x, y) => y.avax - x.avax)[0] || list[0];
    for (const e of [pick].concat(list.filter((x) => x !== pick)).filter(Boolean).slice(0, 3)) {
      items.push({ k: e.k, what: VERB[e.k] || e.k, prep: PREP[e.k] || '', amount: e.avax > 0 ? fmt(e.avax) : e.amt > 0 ? fmt(e.amt) : '', token: e.avax > 0 ? 'AVAX' : e.amt > 0 ? (e.sym || 'a token') : '',
        with: e.cp ? o.nameOf(e.cp) : '', fn: e.fn || '', at: o.time(e.t * 1000) });
    }
    const f = { label: w.label, kind: w.kind, count: list.length, items, hits: res.hits || 0, capped: !!res.more };   // no clock time for 'since': the explorer's answers can lag a few minutes behind a check
    if (code) f.code = { impl: code.impl ? { from: code.impl.from ? short(code.impl.from) : '', to: short(code.impl.to) } : null, verified: code.verified ? code.verified.name || 'yes' : null, unverified: !!code.unverified, proxy: code.proxy ? code.proxy.now : null };
    if (res.busy) f.busy = { hits: res.busy.hits, times: res.busy.times };
    if (o.all && w.kind === 'contract') f.all = true;
    return f;
  }
  const item1 = (x) => (x.k === 'hit' ? `${x.with || 'someone'} used it${x.fn ? ' (' + x.fn + ')' : ''}${x.amount ? ' with ' + x.amount + ' AVAX' : ''} at ${x.at}`
    : `${x.what}${x.amount ? ' ' + x.amount + ' ' + x.token : ''}${x.with ? (x.prep ? ' ' + x.prep + ' ' : ' ') + x.with : ''}${x.fn && !x.amount ? ' (' + x.fn + ')' : ''} at ${x.at}`);
  /** the app's own words for one address: plain, and every number from the facts */
  function noticeText(f) {
    const L = f.label, since = ' since its last look', n = `${f.hits}${f.capped ? ' or more' : ''}`;
    if (f.code) {
      if (f.code.impl) return `${L}: its proxy now points to a new implementation, ${f.code.impl.to}${f.code.impl.from ? ` (it was ${f.code.impl.from})` : ''}.`;
      if (f.code.verified) return `${L}: its source code is now verified on Snowtrace${f.code.verified !== 'yes' ? ` (${f.code.verified})` : ''}.`;
      if (f.code.unverified) return `${L}: Snowtrace no longer shows verified source code for it.`;
      if (f.code.proxy != null) return `${L} is ${f.code.proxy ? 'now' : 'no longer'} a proxy contract.`;
    }
    if (f.busy) return `${L} is busier than usual: ${n} interactions${since}, about ${f.busy.times} times its usual pace.`;
    if (f.all && !f.items.length) return `${L}: ${n} new ${f.hits === 1 && !f.capped ? 'interaction' : 'interactions'}${since}.`;
    if (!f.items.length) return '';
    if (f.count === 1) return f.items[0].k === 'hit' ? `${L}: ${item1(f.items[0])}.` : `${L} ${item1(f.items[0])}.`;
    const what = f.kind === 'contract' && f.all ? 'new interactions' : f.items.every((x) => x.amount) ? 'new transfers' : 'new transactions';
    return `${L}: ${f.count} ${what}. The ${f.items[0].token === 'AVAX' ? 'biggest' : 'newest'}: ${item1(f.items[0])}.`;
  }
  /** one notice for the whole check: [{label, text, sev}] -> {title, severity, text} (at most 500 characters: the chat's limit) */
  function combine(parts, appTitle) {
    const P = parts.filter((p) => p && p.text), rank = { info: 0, watch: 1, warning: 2 };
    const sev = P.reduce((s, p) => (rank[p.sev] > rank[s] ? p.sev : s), 'info');
    let text = ''; for (const p of P) { const t = (text ? ' ' : '') + p.text; if ((text + t).length > 500) break; text += t; }
    return { title: P.length === 1 ? `${appTitle} · ${P[0].label}` : `${appTitle} · ${P.length} addresses`, severity: sev, text };
  }

  // ---- Juli's words, kept only when grounded: every number in the data (the Kit's K.facts), no advice of any kind, no guess about who is
  // behind an address, and no name the data does not have
  const ADVICE = /\b(buy|buys|buying|bought|sell|sells|selling|sold|hold|holds|holding|hodl|invest\w*|trad(e|es|ed|ing|er|ers)|profit\w*|loss(es)?|price\w*|pric(ed|ing)|bullish|bearish|moon\w*|pump\w*|dump\w*|should|shouldn't|must|recommend\w*|advice|advis\w*|suggest\w*|opportunit\w*|worth|value|valued|signal\w*|whale\w*|smart money|accumulat\w*|risk\w*|safe|unsafe|scam\w*|rug\w*|warning sign)\b|\$\s?\d/i;
  const OWNER = /\b(owner\w*|owned|owns|belong\w*|person|people|individual\w*|someone|somebody|anyone|he|she|his|her|hers|him|himself|herself|identity|identit\w*|anonymous|team|founder\w*|ceo|insider\w*|hacker\w*|thie(f|ves)|criminal\w*|suspicious|launder\w*|company|firm|fund|institution\w*|exchange'?s? (wallet|account))\b/i;
  const OKW = new Set(['AVAX', 'Avalanche', 'C-Chain', 'Snowtrace', 'Routescan', 'Juli', 'Wallet', 'Watch', 'UTC', 'AM', 'PM', 'I', 'It', 'Its', 'It’s', "It's", 'The', 'A', 'An', 'In', 'On', 'At', 'Since', 'This', 'That', 'These', 'Those', 'There', 'No', 'New', 'And', 'But', 'Also', 'Both', 'One', 'Two', 'Three', 'Today', 'Yesterday', 'Tonight', 'Most', 'Mostly', 'Usually', 'Over', 'Within', 'From', 'After', 'Before', 'During', 'About', 'Just', 'Recently', 'Here', 'Note', 'Its', 'Each', 'Every', 'Some', 'All', 'Other', 'Another', 'Then', 'Meanwhile', 'Overall', 'Typically', 'Often', 'With', 'For', 'Of', 'To', 'By', 'As', 'Activity', 'Transfers', 'Interactions'].concat(WD, WD.map((d) => d.slice(0, 3)), MON, ['January', 'February', 'March', 'April', 'June', 'July', 'August', 'September', 'October', 'November', 'December']));
  // words that may start a sentence (capitalised only because they come first: "Typical sizes run from ..."); a name never passes this way
  const COMMON = new Set(['typical', 'typically', 'generally', 'commonly', 'frequently', 'regularly', 'recently', 'lately', 'additionally', 'notably', 'overall',
    'mostly', 'usually', 'often', 'its', 'they', 'their', 'these', 'this', 'that', 'there', 'the', 'a', 'an', 'in', 'on', 'at', 'since', 'during', 'from', 'with',
    'for', 'of', 'to', 'by', 'as', 'and', 'but', 'also', 'both', 'each', 'every', 'some', 'all', 'most', 'many', 'few', 'activity', 'transfers', 'transactions',
    'interactions', 'sizes', 'amounts', 'tokens', 'token', 'balance', 'it', 'when', 'while', 'over', 'within', 'about', 'around', 'between', 'after', 'before', 'then', 'here', 'note']);
  function unknownNames(line, factsText) {
    const s = String(line), low = factsText.toLowerCase(), out = new Set(), re = /[A-Z][A-Za-z0-9.$_+’'-]*[A-Za-z0-9]|[A-Z]/g;
    let m;
    while ((m = re.exec(s))) {
      const w = m[0]; if (OKW.has(w) || factsText.includes(w)) continue;
      const before = s.slice(0, m.index), first = !before.trim() || /[.!?:;–—]\s*$/.test(before);
      if (first && (COMMON.has(w.toLowerCase()) || low.includes(w.toLowerCase()))) continue;   // a common word that starts a sentence
      out.add(w);
    }
    return [...out];
  }
  /** -> {ok: true, line} or {ok: false, why} (why: for the app's own log, in plain words) */
  function checkLine(line, facts, factsFn) {
    const s = clip(line, 400);
    if (s.length < 8) return { ok: false, why: 'there was no answer' };
    if (/https?:|www\.|[<>{}`]|\.(com|io|net|org|xyz)\b/i.test(s)) return { ok: false, why: 'it had a web address or code in it' };
    if (ADVICE.test(s)) return { ok: false, why: 'it sounded like advice' };
    if (OWNER.test(s)) return { ok: false, why: 'it guessed about who is behind an address' };
    const chk = factsFn(s, facts);
    if (!chk.ok) return { ok: false, why: `${chk.missing.slice(0, 3).join(', ')} ${chk.missing.length > 1 ? 'are' : 'is'} not in Snowtrace’s data` };
    const unk = unknownNames(s, JSON.stringify(facts));
    if (unk.length) return { ok: false, why: `it used a name that is not in the data (${unk.slice(0, 2).join(', ')})` };
    return { ok: true, line: s };
  }
