  nb.put('habits:' + w.address, { text: text.slice(0, 600), data: Object.assign({}, data, { juli: text ? 'done' : why === 'Juli is not downloaded' ? 'none' : 'waiting', juliAt: Date.now() }),
    evidence: [{ source: 'Snowtrace (public data)', at: data.at }].concat(text ? [{ source: 'Juli, from those numbers', at: Date.now() }] : []) });
  ctx.log(text ? `Juli described ${w.label}'s habits` : `Left out Juli's words on ${w.label}'s habits (${why})`);
}

// ===== IDLE TASK 3: tidy =====
async function tidy() {
  const L = new Set(watched().map((w) => w.address)), old = Date.now() - 14 * 864e5;
  for (const e of nb.all) {
    const a = (e.data && e.data.address) || (String(e.key || '').match(/^(st|ev|code|habits):(0x[0-9a-f]{40})$/) || [])[2];
    if (a && !L.has(a)) { nb.remove(e.id); continue; }   // an address no longer watched: what was kept for it goes
    if (e.kind === 'change' && (e.upd < old || (e.shelf === 'dismissed' && e.upd < Date.now() - 3 * 864e5))) nb.remove(e.id);
  }
  nb.prune(); badge();
  return { active: false };
}

const newWaiting = () => watched().some((w) => !stOf(w.address)) || !!K.load('ww.cut', 0);   // a new address, or a look a busy phone cut short
K.agent({ goal: 'Keep an eye on the addresses I watch and tell me what changed', budgetS: 95, tasks: [{ id: 'watch', every: EVERY(), run: watch, due: newWaiting }, { id: 'habits', every: 1440, run: habits, due: habitsWaiting }, { id: 'tidy', every: 720, run: tidy }] });
// the check the host runs (at most every 15 minutes, only when the phone is idle: the host's rules): the tasks that are due (they share
// its time), then when the next one is wanted (the host keeps it between the trigger's 15 and 60 minutes); after a failed look at
// Snowtrace the next one waits longer; a look the phone cut short comes back at the next idle check
async function check() {
  DEADLINE = Date.now() + 100e3;
  const due = (id, every, d) => { let w = false; try { w = !!(d && d()); } catch (e) { /* */ } return w || Date.now() - K.agent.last(id) >= every * 60e3 - 30e3; };
  const p = K.load('ww.pause', null), paused = p && p.until > Date.now();
  if (!paused && due('watch', EVERY(), newWaiting)) await K.agent.run('watch');
  if (!paused && (DEADLINE - Date.now()) / 1000 > 40 && due('habits', 1440, habitsWaiting)) await K.agent.run('habits');
  if (due('tidy', 720)) await K.agent.run('tidy');
  const err = (K.load('ww.err', null) || {}).n || 0, every = EVERY() * 2 ** err;
  const wait = paused ? Math.ceil((p.until - Date.now()) / 60e3) : K.load('ww.cut', 0) ? 15 : Math.ceil((every * 60e3 - (Date.now() - K.agent.last('watch'))) / 60e3);
  return { active: true, next: Math.max(15, Math.min(60, wait)) };
}
if (window.p0) p0.onCheck(check);

// ===== ACTIVE TASKS (the open app): add or remove an address, say "Got it" =====
const ui = { addr: '', label: '', kind: 0, open: null, contentH: 1200, msg: '' };
function addAddress() {
  const a = ui.addr.trim(), L = watched();
  if (!WW.isAddr(a)) { ui.msg = 'That is not an Avalanche C-Chain address: 0x and 40 letters or digits.'; K.sfx('error'); return; }
  if (L.some((w) => w.address === a.toLowerCase())) { ui.msg = 'It is on the list already.'; K.sfx('error'); return; }
  if (L.length >= 5) { ui.msg = 'Five addresses at most: remove one first.'; K.sfx('error'); return; }
  const label = ui.label.trim().slice(0, 20) || WW.short(a), kind = ui.kind ? 'contract' : 'wallet';
  const rm = removed().filter((x) => x !== a.toLowerCase()); K.save('ww.removed.v1', rm);
  const e = nb.add({ kind: 'addr?', title: label, data: { address: a.toLowerCase(), label, kind } });
  nb.confirm(e.id, { kind: 'addr', title: label, evidence: [{ source: 'Added by you', at: Date.now() }] });   // the person's own tap
  ui.addr = ''; ui.label = ''; ui.msg = ''; K.blurInputs(); K.sfx('success');
  K.toast(`Watching ${label}`, { tone: 'good', icon: 'eye' });
  K.agent.log(`You added ${label}`);
  if (window.p0) K.agent.run('watch');   // its first look now (no Juli in the open app)
}
function removeAddress(w) {
  if (w.from === 'slot') { const rm = removed(); rm.push(w.address); K.save('ww.removed.v1', [...new Set(rm)].slice(-40)); }
  for (const e of nb.list('confirmed', 'addr')) if ((e.data || {}).address === w.address) nb.remove(e.id);
  for (const k of ['st:', 'ev:', 'code:', 'habits:']) { const e = nb.get(k + w.address); if (e) nb.remove(e.id); }
  for (const e of nb.list('suspected', 'change')) if ((e.data || {}).address === w.address) nb.remove(e.id);
  K.agent.log(`You removed ${w.label}`); badge(); K.sfx('back');
}
function onReview(act) { if (act.action === 'no') { nb.dismiss(act.entry.id); K.sfx('tap'); badge(); } }

// ===== DRAWING (the open app only: an unseen check never gets here) =====
function setup() {
  K.setup({ mode: 'dark', accent: ACCENT });
  K.scene('main', drawMain);
  if (window.p0 && p0.mode === 'run' && watched().length && Date.now() - K.agent.last('watch') > EVERY() * 60e3) K.agent.run('watch');   // a fresh look when it opens
}
function draw() { K.render(); }

function drawMain() {
  K.backdrop({ top: K.C.bg, bottom: K.darken(ACCENT, 0.86), glow: [{ x: K.W * 0.85, y: 70, r: 260, color: K.alpha(ACCENT, 0.13) }, { x: K.W * 0.1, y: K.H * 0.8, r: 220, color: K.alpha('#8B6CFF', 0.12) }] });
  const L = watched(), rv = nb.review().length, pz = pauseText();
  const sub = L.length ? `Watching ${plural(L.length, 'address')}` + (rv ? ` · ${rv} to look at` : '') : 'Add an address to watch';
  const y0 = K.navBar.top(sub) + 8, clipY = K.navBar.bottom(), x = K.S.l, w = K.W - 2 * K.S.l;
  const off = K.scroll('main', 0, clipY, K.W, K.H - clipY, ui.contentH);
  K.clip(0, clipY, K.W, K.H - clipY, () => { ui.contentH = body(x, y0 - off, w, pz) + off - y0 + 40; });
  const tap = K.navBar(TITLE, off, { sub, right: L.length ? { id: 'refresh', icon: 'refresh' } : undefined });
  if (tap === 'refresh' && !K.agent.busy()) {   // the person's own look: at most once a minute (Snowtrace's cap still counts every request)
    if (Date.now() - K.agent.last('watch') < 60e3) K.toast('Looked less than a minute ago', { icon: 'clock', ms: 1600 });
    else K.agent.run('watch').then(() => K.toast(pauseText() || 'Checked', { tone: pauseText() ? 'warn' : 'good', icon: 'refresh', ms: 1600 }));
  }
}

function body(x, y, w, pz) {
  const y0 = y;
  if (pz) {   // Snowtrace's free limit: plainly, before anything else
    const h = K.paraHeight(pz, w - 60, 'callout', { maxLines: 3 }) + 26;
    K.card(x, y, w, h, { r: 16, fill: K.alpha(K.C.warn, 0.14) });
    K.icon('clock', x + 24, y + h / 2, 18, K.C.warn);
    K.para(pz, x + 46, y + 13, w - 60, 'callout', K.C.text, { maxLines: 3 });
    y += h + 12;
  }
  const rv = nb.review().sort((a, b) => b.upd - a.upd);
  if (rv.length) {   // 1. what changed: the review list
    K.text('WHAT CHANGED', x, y + 14, 'label', K.C.text2); y += 26;
    const r = K.review('rv', x, y, w, rv, { yes: () => null, no: () => 'Got it', ask: () => false,
      color: (e) => ((e.data || {}).sev === 'warning' ? K.C.bad : (e.data || {}).sev === 'watch' ? K.C.warn : ACCENT) });
    if (r.act) onReview(r.act);
    y += r.h + 6;
  }
  const L = watched();   // 2. the addresses
  if (L.length) { K.text('WATCHING', x, y + 18, 'label', K.C.text2); y += 30; for (const a of L) y = addrCard(a, x, y, w) + 10; }
  else y += K.empty(K.W / 2, y + 6, 'eye', 'Nothing to watch yet', 'Paste a public Avalanche address below, or try the public WAVAX contract.', { w: w - 40 }) + 6;
  if (!L.length) { if (K.button('try-wavax', x, y, w, 44, 'Try the public WAVAX contract', { style: 'tinted', icon: 'sparkle' })) { ui.addr = EXAMPLE.address; ui.label = EXAMPLE.label; ui.kind = 1; addAddress(); } y += 56; }
  y = addBox(x, y, w, L.length);   // 3. add an address
  const logs = K.agent.logs().slice(0, 6);   // 4. what the app did
  if (logs.length) {
    K.text(('What ' + TITLE + ' did').toUpperCase(), x, y + 18, 'label', K.C.text2); y += 30;
    const lh = 42; K.card(x, y, w, logs.length * lh + 8, { r: 16 });
    logs.forEach((l, i) => { const ly = y + 4 + i * lh; if (i) K.line(x + 14, ly, x + w - 14, ly, K.C.line, 1); K.text(l.text, x + 14, ly + 19, 'footnote', K.C.text, { maxW: w - 28 }); K.text(K.fmt.ago(l.at) + (l.n > 1 ? ` · ${l.n} times` : ''), x + 14, ly + 35, 'caption', K.C.text3); });
    y += logs.length * lh + 18;
  }
  const q = quota();
  y += K.para(`Data: Snowtrace, the public Avalanche explorer. Powered by Routescan.io APIs: routescan.io and @routescan_io on X (the links are at the foot of the screen).${q ? ` Snowtrace requests today: ${q.used.toLocaleString('en-US')} of ${q.cap.toLocaleString('en-US')}, shared by your apps (p0pc0rn stops at half of Snowtrace’s free limit).` : ''} ${TITLE} only reads public data: it never touches a wallet or moves anything, and it gives no advice. Juli’s words are checked against Snowtrace’s numbers, and she never guesses who is behind an address. It looks at most every ${EVERY()} minutes while p0pc0rn is open, and only when your phone is idle.`, x, y + 8, w, 'caption', K.C.text3) + 12;
  return y - y0;
}

const KIND_ICON = { out: 'arrowUp', tout: 'arrowUp', in: 'arrowDown', tin: 'arrowDown', call: 'bolt', fail: 'alert', hit: 'user' };
const evLine = (e) => (e.k === 'hit' ? `Used${e.fn ? ' (' + e.fn + ')' : ''}${e.amount ? ' with ' + e.amount + ' AVAX' : ''} by ${nameOf(e.cp)}`
  : e.k === 'call' ? `Used ${nameOf(e.cp)}${e.fn ? ' (' + e.fn + ')' : ''}` : e.k === 'fail' ? `A transaction that failed${e.cp ? ' (' + nameOf(e.cp) + ')' : ''}`
    : `${e.k === 'out' || e.k === 'tout' ? 'Sent' : 'Received'} ${e.amount} ${e.token || 'of a token'} ${e.k === 'out' || e.k === 'tout' ? 'to' : 'from'} ${nameOf(e.cp)}`);
function addrCard(a, x, y, w) {
  const s = stOf(a.address), tag = tagOf(a.address), open = ui.open === a.address, code = (nb.get('code:' + a.address) || {}).data;
  const ev = open ? (((nb.get('ev:' + a.address) || {}).data || {}).list || []).slice(0, 6) : [];
  const hb = open && a.kind === 'wallet' ? habitsOf(a.address) : null, hd = hb ? hb.data || {} : null;
  const tw = w - 32, para = (t, r, ml) => (t ? K.paraHeight(t, tw, r, { maxLines: ml }) : 0);
  const hText = hb && hb.text ? hb.text : '', hLines = hd ? (hd.lines || []) : [];
  const evH = open ? (ev.length ? ev.length * 40 + 8 : 26) : 0;
  const habH = open && a.kind === 'wallet' ? 30 + (hText ? para(hText, 'callout', 6) + 8 : 0) + hLines.reduce((sum, l) => sum + para(l, 'footnote', 3) + 4, 0) + (hb ? 22 : 26) : 0;
  const h = 132 + (code ? 20 : 0) + evH + habH + 54;
  K.card(x, y, w, h, { r: 18 });
  const chip = a.kind === 'contract' ? 'Contract' : 'Wallet';
  K.text(a.label, x + 16, y + 30, 'headline', K.C.text, { maxW: w - 48 - K.chipWidth(chip) });
  K.chip(x + w - 16 - K.chipWidth(chip), y + 13, chip, { color: a.kind === 'contract' ? '#8B6CFF' : ACCENT });
  K.text(WW.short(a.address) + (tag ? ' · ' + tag : ''), x + 16, y + 52, 'subhead', K.C.text2, { family: 'MONO', maxW: tw });
  const bal = s && s.bal != null ? WW.fmt(WW.units(s.bal, 18)) + ' AVAX' : '—';
  K.text(bal, x + 16, y + 86, 'title2', K.C.text, { maxW: tw });
  const status = !s ? 'Not checked yet' : `Checked ${K.fmt.ago(s.lastAt)}` + (s.lastAct ? ` · last activity ${timeOf(s.lastAct)}` : '');
  K.icon(s ? 'checkCircle' : 'clock', x + 24, y + 110, 15, s ? K.C.good : K.C.text3);
  K.text(status, x + 40, y + 115, 'footnote', K.C.text3, { maxW: w - 56 });
  let yy = y + 132;
  if (code) { K.text((code.verified ? 'Verified' + (code.name ? ' · ' + code.name : '') : 'Source not verified') + (code.proxy ? ` · a proxy for ${WW.short(code.impl)}` : ''), x + 16, yy + 2, 'caption', K.C.text3, { maxW: tw }); yy += 20; }
  if (open) {
    K.line(x + 16, yy, x + w - 16, yy, K.C.line, 1);
    if (!ev.length) { K.text(s ? 'Nothing new since you started watching it.' : 'Its first look comes with the next check.', x + 16, yy + 18, 'footnote', K.C.text3, { maxW: tw }); yy += 26; }
    ev.forEach((e, i) => {
      const ry = yy + 4 + i * 40;
      K.icon(KIND_ICON[e.k] || 'info', x + 26, ry + 20, 15, e.k === 'out' || e.k === 'tout' ? K.C.warn : e.k === 'fail' ? K.C.bad : ACCENT);
      K.text(evLine(e), x + 46, ry + 17, 'subhead', K.C.text, { maxW: w - 62 });
      K.text(timeOf(e.t * 1000), x + 46, ry + 33, 'caption', K.C.text3);
    });
    if (ev.length) yy += ev.length * 40 + 8;
    if (a.kind === 'wallet') {
      K.text('HABITS', x + 16, yy + 20, 'label', K.C.text2); yy += 30;
      if (!hb) { K.text('Juli notes its habits at a check, once a day.', x + 16, yy + 6, 'footnote', K.C.text3, { maxW: tw }); yy += 26; }
      else {
        if (hText) { K.para(hText, x + 16, yy, tw, 'callout', K.C.text, { maxLines: 6 }); yy += para(hText, 'callout', 6) + 8; }
        for (const l of hLines) { K.para(l, x + 16, yy, tw, 'footnote', K.C.text2, { maxLines: 3 }); yy += para(l, 'footnote', 3) + 4; }
        K.text((hText ? 'Juli, from Snowtrace’s public data' : 'From Snowtrace’s public data') + ' · ' + K.fmt.ago(hd.at) + ' · descriptive only', x + 16, yy + 12, 'caption', K.C.text3, { maxW: tw }); yy += 22;
      }
    }
  }
  const bw = (tw - 8) / 2, by = y + h - 52;
  if (K.button('open:' + a.address, x + 16, by, bw, 38, open ? 'Less' : a.kind === 'wallet' ? 'Activity & habits' : 'Activity', { style: 'secondary', icon: open ? 'chevronUp' : 'chevronDown' })) ui.open = open ? null : a.address;
  if (K.button('rm:' + a.address, x + 24 + bw, by, bw, 38, 'Remove', { style: 'ghost', icon: 'trash' })) removeAddress(a);
  return y + h;
}

function addBox(x, y, w, n) {
  K.text('ADD AN ADDRESS', x, y + 18, 'label', K.C.text2); y += 28;
  if (n >= 5) { y += K.para('Five addresses at most: remove one to add another.', x, y + 2, w, 'footnote', K.C.text3) + 10; return y; }
  ui.addr = K.input('addr', x, y, w, 48, ui.addr, { placeholder: '0x… a public Avalanche address', icon: 'search', onEnter: addAddress }); y += 56;
  ui.label = K.input('label', x, y, w, 48, ui.label, { placeholder: 'A short name (e.g. Treasury)', icon: 'tag', onEnter: addAddress }); y += 56;
  ui.kind = K.segmented('kind', x, y, w, ['Wallet', 'Contract'], ui.kind); y += 46;
  if (K.button('add', x, y, w, 46, 'Watch it', { style: 'primary', icon: 'eye', disabled: ui.addr.trim().length < 42 })) addAddress();
  y += 56;
  if (ui.msg) y += K.para(ui.msg, x, y, w, 'footnote', K.C.warn) + 8;
  y += K.para('Only the address goes to Snowtrace, to read its public activity. The name you give it stays on this phone.', x, y + 2, w, 'caption', K.C.text3) + 14;
  return y;
}
